import pandas as pd, numpy as np
# Gather iron dose experiments
files = {1:experiment_1_csv,3:experiment_3_csv,4:experiment_4_csv,6:experiment_6_csv,
         8:experiment_8_csv,9:experiment_9_csv,10:experiment_10_csv,11:experiment_11_csv,12:experiment_12_csv}
for k,f in files.items():
    try:
        df=pd.read_csv(f)
        cols=[c for c in df.columns]
        # find iron col and yield
        ycol=[c for c in df.columns if 'Yield' in c]
        fecol=[c for c in df.columns if 'ron' in c or 'Fe' in c]
        print(k, "cols:", cols[:8])
        if ycol:
            print("   yield mean:", df[ycol[0]].mean().round(3))
        for fc in fecol:
            print("   ",fc,"mean:",df[fc].mean().round(3))
    except Exception as e:
        print(k,"err",e)

